exercises.code:
module com.example.moda {
    exports com.example.moda.api; // publico para quien haga requires com.example.moda
    // com.example.moda.internal NO esta exportado: invisible fuera del modulo
}

module com.example.modb {
    requires com.example.moda; // ahora modb puede ver lo que moda exporta
}

module com.example.moda {
    exports com.example.moda.api to com.example.modb; // solo modb puede verlo
}

// modulo que ofrece el servicio
module com.example.modg {
    requires com.example.modf;
    provides com.example.modf.api.Service with com.example.modg.impl.ServiceImpl;
}

// modulo que consume el servicio
module com.example.modh {
    requires com.example.modf;
    uses com.example.modf.api.Service;
}

module com.example.modh {
    requires com.example.modf;
    _____ com.example.modf.api.Service;
}

// estructura de carpetas:
// src/com.example.moda/module-info.java
// src/com.example.moda/com/example/moda/api/Greeter.java
// src/com.example.modb/module-info.java
// src/com.example.modb/com/example/modb/Main.java

javac --module-source-path src -d out src/com.example.moda/module-info.java src/com.example.moda/com/example/moda/api/Greeter.java src/com.example.modb/module-info.java src/com.example.modb/com/example/modb/Main.java

// con clase explicita:
java -p mods -m com.example.app/com.example.app.Main

// si el jar fue creado con --main-class, alcanza con:
java -p mods -m com.example.app

