// codigo Java:
ServiceLoader<Service> loader = ServiceLoader.load(Service.class);
for (Service s : loader) {
    System.out.println(s.name());
}

// opcion 1: constructor publico sin argumentos
public class ServiceImpl implements Service {
    public ServiceImpl() {}
    public String name() { return "impl A"; }
}

// opcion 2: metodo estatico provider()
public class StaticFactoryImpl implements Service {
    private StaticFactoryImpl() {}
    public static Service provider() {
        return new StaticFactoryImpl();
    }
    public String name() { return "impl B"; }
}

