exercises.code:
// build/lib con clases compiladas SIN module-info.java, puesta en -classpath (no -p):
java -cp legacy.jar com.example.Main

// intentar esto desde un modulo con nombre falla:
module com.example.app {
    requires com.foo.bar; // com.foo.bar esta en el classpath, no en el module path
}

// foo-bar-utils-2.5.jar no tiene module-info.class
// puesto en el module path:
java -p mods -m com.example.app/com.example.app.Main

// jar --describe-module reporta:
// foo.bar.utils@2.5 automatic

// foo-bar-utils-2.5.jar contiene el paquete com.foo.bar
// gadget-lib-1.0.jar TAMBIEN contiene el paquete com.foo.bar
// ambos puestos juntos en el module path:

java --module-path "foo-bar-utils-2.5.jar:gadget-lib-1.0.jar" ...

// java.lang.module.ResolutionException:
// Module gadget.lib contains package com.foo.bar,
// module foo.bar.utils exports package com.foo.bar to gadget.lib

// sin --add-opens:
// java.lang.IllegalAccessException: class com.example.modo.Main (in module com.example.modo)
// cannot access class com.example.modn.internal.Secret (in module com.example.modn)
// because module com.example.modn does not export com.example.modn.internal to module com.example.modo

// con la flag agregada al comando java:
java --add-opens com.example.modn/com.example.modn.internal=com.example.modo -p out -m com.example.modo/com.example.modo.Main
